ALTER TABLE public.dhg_invitations ADD COLUMN claimed_by uuid;
CREATE OR REPLACE FUNCTION public.claim_dhg_access() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE matched public.dhg_invitations%ROWTYPE; BEGIN IF auth.uid() IS NULL OR (auth.jwt()->>'email') IS NULL THEN RETURN false; END IF; SELECT * INTO matched FROM public.dhg_invitations WHERE lower(email)=lower(auth.jwt()->>'email') AND role='staff' FOR UPDATE; IF NOT FOUND THEN RETURN public.is_staff(auth.uid()); END IF; IF matched.claimed_by IS NOT NULL AND matched.claimed_by <> auth.uid() THEN RETURN false; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'staff') ON CONFLICT DO NOTHING; UPDATE public.dhg_invitations SET claimed_by=auth.uid(), claimed_at=coalesce(claimed_at,now()) WHERE id=matched.id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.claim_dhg_access() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_dhg_access() TO authenticated;
CREATE FUNCTION public.revoke_dhg_staff(_invitation_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target public.dhg_invitations%ROWTYPE; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO target FROM public.dhg_invitations WHERE id=_invitation_id AND role='staff' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Acesso não encontrado'; END IF; IF target.claimed_by IS NOT NULL THEN DELETE FROM public.user_roles WHERE user_id=target.claimed_by AND role='staff'; END IF; DELETE FROM public.dhg_invitations WHERE id=target.id; END $$;
REVOKE ALL ON FUNCTION public.revoke_dhg_staff(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.revoke_dhg_staff(uuid) TO authenticated;